import {
  Injectable,
  HttpException,
  HttpStatus,
  Logger,
  OnModuleInit,
  OnModuleDestroy,
} from '@nestjs/common';
import * as crypto from 'crypto';
import Redis from 'ioredis';

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: number;
}

/**
 * Branded type representing a verified, trusted internal Redis rate-limit key.
 * Can only be generated by the service's internal key derivation pipeline.
 */
export type NormalizedRateLimitKey = string & { readonly __brand: unique symbol };

/**
 * Whitelist of supported application rate-limit action namespaces.
 * Prevents arbitrary user strings from spoofing legitimate action namespaces
 * or embedding sensitive identifiers into action prefixes.
 */
export const SUPPORTED_RATE_LIMIT_ACTIONS = new Set<string>([
  'reg_ip',
  'login_ip',
  'login_email',
  'verify_ip',
  'resend_ip',
  'resend_user',
  'forgot_ip',
  'forgot_email',
  'reset_ip',
  'reset_token',
  // Tenant rate-limiting namespaces
  'tenant_invite_create',
  'tenant_invite_accept',
  'tenant_transfer_ownership',
  'tenant_member_mutation',
  // Diagnostic and test namespaces permitted for internal testing
  'test_ip',
  'test_reset',
  'test_key',
  'auth_action',
]);

export const GENERIC_RATE_LIMIT_NAMESPACE = 'generic';

interface InMemoryBucket {
  count: number;
  resetAt: number;
}

// Atomic Redis sliding window increment Lua script
const ATOMIC_RATE_LIMIT_LUA = `
local key = KEYS[1]
local maxAttempts = tonumber(ARGV[1])
local windowMs = tonumber(ARGV[2])

local current = redis.call('INCR', key)
if current == 1 then
  redis.call('PEXPIRE', key, windowMs)
end

local ttl = redis.call('PTTL', key)
if ttl < 0 then
  redis.call('PEXPIRE', key, windowMs)
  ttl = windowMs
end

return { current, ttl }
`;

@Injectable()
export class RateLimiterService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(RateLimiterService.name);
  private redisClient: Redis | null = null;
  private isRedisConnected = false;
  private memoryBuckets: Map<string, InMemoryBucket> = new Map();
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor() {
    // Setup in-memory pruning for development/test fallback
    if (process.env.NODE_ENV !== 'test') {
      this.cleanupInterval = setInterval(() => {
        this.pruneExpiredBuckets();
      }, 5 * 60 * 1000);
      if (this.cleanupInterval.unref) {
        this.cleanupInterval.unref();
      }
    }
  }

  async onModuleInit() {
    const redisUrl = process.env.REDIS_URL;

    if (redisUrl && redisUrl.trim() !== '') {
      try {
        this.redisClient = new Redis(redisUrl, {
          lazyConnect: true,
          maxRetriesPerRequest: 1,
          enableOfflineQueue: false,
          connectTimeout: 5000,
          retryStrategy: (times) => {
            if (times > 3) return null;
            return Math.min(times * 100, 1000);
          },
        });

        this.redisClient.on('error', (_err) => {
          this.isRedisConnected = false;
        });

        this.redisClient.on('connect', () => {
          this.isRedisConnected = true;
          this.logger.log('Shared Redis rate limiter connected successfully.');
        });

        this.redisClient.on('close', () => {
          this.isRedisConnected = false;
        });

        await this.redisClient.connect();
        this.isRedisConnected = true;
      } catch (_err) {
        this.isRedisConnected = false;
        if (process.env.NODE_ENV === 'production') {
          this.logger.error('Failed to connect to shared Redis rate limiter in production.');
        } else {
          this.logger.warn(
            'Redis connection failed. Using local in-memory rate limiter for non-production environment.'
          );
        }
      }
    } else if (process.env.NODE_ENV === 'production') {
      this.logger.error('REDIS_URL is not configured in production environment.');
    }

    // Verify HMAC rate-limit secret configuration in production
    if (process.env.NODE_ENV === 'production') {
      try {
        this.getHmacSecret();
      } catch (_err) {
        this.logger.error(
          'RATE_LIMIT_SECRET is not configured or insufficiently strong in production environment.'
        );
      }
    }
  }

  async onModuleDestroy() {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
    if (this.redisClient) {
      try {
        await this.redisClient.quit();
      } catch {
        // Ignore disconnect errors
      }
      this.redisClient = null;
      this.isRedisConnected = false;
    }
  }

  /**
   * Retrieves the HMAC secret used for privacy-preserving rate-limit identifier hashing.
   *
   * In production (NODE_ENV=production):
   * Requires a shared secret of at least 32 characters configured via RATE_LIMIT_SECRET.
   * If missing or set to placeholder, fails closed with HTTP 503 to prevent PII exposure.
   *
   * In development/test:
   * Uses a stable fallback string to allow deterministic local testing and shared rate-limiting
   * without requiring manual secret configuration.
   */
  private getHmacSecret(): string {
    const configuredSecret = process.env.RATE_LIMIT_SECRET?.trim();
    if (
      configuredSecret &&
      configuredSecret.length >= 32 &&
      !configuredSecret.includes('change-this')
    ) {
      return configuredSecret;
    }

    if (process.env.NODE_ENV === 'production') {
      this.logger.error(
        'CRITICAL SECURITY CONFIGURATION ERROR: RATE_LIMIT_SECRET must be configured ' +
          'with a secure secret of at least 32 characters in production. Failing closed.'
      );
      throw new HttpException(
        {
          statusCode: HttpStatus.SERVICE_UNAVAILABLE,
          message: 'Rate limit service configuration error. Protected operation rejected.',
          error: 'Service Unavailable',
        },
        HttpStatus.SERVICE_UNAVAILABLE
      );
    }

    return 'feedbackhub_dev_rate_limit_hmac_secret_stable_32chars_minimum';
  }

  /**
   * Cryptographically hashes a sensitive rate-limit identifier (email, IP, token hash)
   * using HMAC-SHA256 with the shared cluster secret.
   *
   * Threat Model & Privacy Defense:
   * Low-entropy identifiers such as IPv4 addresses (~4.3 billion possible values) and common
   * email addresses are trivial to reverse via precomputed dictionary or rainbow-table attacks
   * if hashed with a plain unsalted or unkeyed SHA-256. Using HMAC with an application-wide
   * shared secret prevents external parties with read access to Redis dumps or monitoring
   * from identifying users or reversing access locations, while ensuring all distributed API
   * instances produce the exact same deterministic key for rate enforcement.
   */
  hashIdentifier(identifier: string): string {
    const secret = this.getHmacSecret();
    return crypto.createHmac('sha256', secret).update(identifier).digest('hex');
  }

  /**
   * Normalizes keys to guarantee case-insensitivity, trim whitespace,
   * prevent formatting bypasses, and prevent PII leakage.
   *
   * Formats keys as: fh:rl:<action>:<hashed-identifier>
   * Where <action> is a clean, readable action name (e.g. login_email, reset_token),
   * and <hashed-identifier> is an HMAC-SHA256 digest of the normalized identifier.
   *
   * This guarantees:
   * 1. Sensitive identifiers (emails, IP addresses, token hashes) are never stored
   *    in plaintext in Redis keys, logs, or memory dumps.
   * 2. Low-entropy identifiers (such as IPv4 addresses) cannot be reversed via
   *    offline dictionary or rainbow-table attacks without the HMAC secret.
   * 3. Consistent, deterministic hashing across all distributed application instances.
   */
  normalizeKey(rawKey: string): string {
    return this.buildNormalizedKey(rawKey);
  }

  /**
   * Internal key generation pipeline enforcing a strict trust boundary between untrusted
   * external strings and trusted internal Redis rate-limit keys.
   *
   * Security & Anti-Bypass Architecture:
   * 1. Untrusted caller strings are NEVER assumed to be pre-normalized, even if they match
   *    the key regex pattern (/^fh:rl:[a-z0-9_]+:[0-9a-f]{64}$/) or contain the 'fh:rl:' prefix.
   * 2. Action namespaces are strictly validated against SUPPORTED_RATE_LIMIT_ACTIONS.
   * 3. Malformed inputs (raw emails/tokens without colons, missing identifiers, inverted actions,
   *    empty inputs, or invalid action names) are safely routed through the secure HMAC-SHA256
   *    pathway under the 'generic' namespace.
   * 4. Raw user-controlled identifiers NEVER appear in Redis keys or internal state.
   */
  private buildNormalizedKey(rawKey: string): NormalizedRateLimitKey {
    let clean = (rawKey ?? '').trim();

    // Strip external 'fh:rl:' prefixes that an attacker might supply to manipulate action parsing
    while (clean.startsWith('fh:rl:')) {
      clean = clean.slice(6).trim();
    }

    // Handle empty or whitespace-only inputs safely via generic HMAC pathway
    if (!clean) {
      const hashedEmpty = this.hashIdentifier('');
      return `fh:rl:${GENERIC_RATE_LIMIT_NAMESPACE}:${hashedEmpty}` as NormalizedRateLimitKey;
    }

    const colonIdx = clean.indexOf(':');
    if (colonIdx === -1) {
      // Input has no colon delimiter (e.g. 'user@example.com', 'raw-token', 'login', etc.)
      // Route the entire sanitized input through the HMAC pathway under the generic namespace
      // to guarantee that no raw sensitive identifier can ever appear in Redis or memory keys.
      const normalizedInput = clean.toLowerCase().replace(/[\r\n\t]/g, '');
      const hashedInput = this.hashIdentifier(normalizedInput);
      return `fh:rl:${GENERIC_RATE_LIMIT_NAMESPACE}:${hashedInput}` as NormalizedRateLimitKey;
    }

    const action = clean
      .slice(0, colonIdx)
      .trim()
      .toLowerCase()
      .replace(/[\r\n\t]/g, '');
    const identifier = clean
      .slice(colonIdx + 1)
      .trim()
      .toLowerCase()
      .replace(/[\r\n\t]/g, '');

    // Validate action namespace and ensure non-empty identifier.
    // If action is invalid (e.g. 'user@example.com:login', 'login:user@example.com', 'reset:token')
    // or if identifier is missing (e.g. 'login_email:'), route the entire input through the generic
    // HMAC pathway to prevent spoofing, collision, or unhashed key emission.
    if (!SUPPORTED_RATE_LIMIT_ACTIONS.has(action) || !identifier) {
      const normalizedInput = clean.toLowerCase().replace(/[\r\n\t]/g, '');
      const hashedInput = this.hashIdentifier(normalizedInput);
      return `fh:rl:${GENERIC_RATE_LIMIT_NAMESPACE}:${hashedInput}` as NormalizedRateLimitKey;
    }

    // Verified action namespace and valid identifier:
    // Always cryptographically hash the identifier via HMAC-SHA256
    const hashedId = this.hashIdentifier(identifier);
    return `fh:rl:${action}:${hashedId}` as NormalizedRateLimitKey;
  }

  /**
   * Check rate limit using shared Redis if available, or memory fallback.
   * In production, fails closed if shared store is unavailable.
   */
  async check(key: string, maxAttempts: number, windowMs: number): Promise<RateLimitResult> {
    const normalizedKey = this.buildNormalizedKey(key);
    return this.checkInternal(normalizedKey, maxAttempts, windowMs);
  }

  /**
   * Assert rate limit for a raw key, throwing HTTP 429 Too Many Requests if exceeded.
   * Invokes checkInternal directly with the derived NormalizedRateLimitKey to prevent
   * accidental double-hashing within internal operations.
   */
  async assert(
    key: string,
    maxAttempts: number,
    windowMs: number,
    message = 'Too many attempts. Please try again later.'
  ): Promise<void> {
    const normalizedKey = this.buildNormalizedKey(key);
    const result = await this.checkInternal(normalizedKey, maxAttempts, windowMs);
    if (!result.allowed) {
      const waitSeconds = Math.ceil((result.resetAt - Date.now()) / 1000);
      throw new HttpException(
        {
          statusCode: HttpStatus.TOO_MANY_REQUESTS,
          message: `${message} Please try again in ${waitSeconds} seconds.`,
          error: 'Too Many Requests',
        },
        HttpStatus.TOO_MANY_REQUESTS
      );
    }
  }

  /**
   * Internal rate limit check on a verified, trusted NormalizedRateLimitKey.
   */
  private async checkInternal(
    normalizedKey: NormalizedRateLimitKey,
    maxAttempts: number,
    windowMs: number
  ): Promise<RateLimitResult> {
    const isProduction = process.env.NODE_ENV === 'production';

    // 1. Preferred Production Shared Store: Redis
    if (this.redisClient && this.isRedisConnected) {
      try {
        const result = (await this.redisClient.eval(
          ATOMIC_RATE_LIMIT_LUA,
          1,
          normalizedKey,
          maxAttempts.toString(),
          windowMs.toString()
        )) as [number, number];

        const currentCount = result[0];
        const ttlMs = result[1];
        const resetAt = Date.now() + (ttlMs > 0 ? ttlMs : windowMs);

        if (currentCount > maxAttempts) {
          return { allowed: false, remaining: 0, resetAt };
        }

        return {
          allowed: true,
          remaining: Math.max(0, maxAttempts - currentCount),
          resetAt,
        };
      } catch (_err) {
        // In production, failure of shared store must FAIL CLOSED
        if (isProduction) {
          this.logger.error('Shared Redis rate-limiter operation failed in production. Failing closed.');
          throw new HttpException(
            {
              statusCode: HttpStatus.SERVICE_UNAVAILABLE,
              message: 'Rate limit service unavailable. Protected operation rejected.',
              error: 'Service Unavailable',
            },
            HttpStatus.SERVICE_UNAVAILABLE
          );
        }
      }
    }

    // In production, running without shared rate limiter is strictly prohibited (Fail Closed)
    if (isProduction) {
      this.logger.error(
        'Shared rate limiter is unavailable in production. Production requests cannot proceed without persistent shared rate limiting.'
      );
      throw new HttpException(
        {
          statusCode: HttpStatus.SERVICE_UNAVAILABLE,
          message: 'Rate limit service unavailable. Protected operation rejected.',
          error: 'Service Unavailable',
        },
        HttpStatus.SERVICE_UNAVAILABLE
      );
    }

    // 2. Development / Test Memory Fallback Driver
    return this.checkMemory(normalizedKey, maxAttempts, windowMs);
  }

  private checkMemory(
    normalizedKey: NormalizedRateLimitKey,
    maxAttempts: number,
    windowMs: number
  ): RateLimitResult {
    const now = Date.now();
    const bucket = this.memoryBuckets.get(normalizedKey);

    if (!bucket || now >= bucket.resetAt) {
      this.memoryBuckets.set(normalizedKey, { count: 1, resetAt: now + windowMs });
      return { allowed: true, remaining: maxAttempts - 1, resetAt: now + windowMs };
    }

    if (bucket.count >= maxAttempts) {
      return { allowed: false, remaining: 0, resetAt: bucket.resetAt };
    }

    bucket.count += 1;
    return { allowed: true, remaining: maxAttempts - bucket.count, resetAt: bucket.resetAt };
  }

  /**
   * Reset rate limit bucket for a key.
   */
  async reset(key: string): Promise<void> {
    const normalizedKey = this.buildNormalizedKey(key);
    await this.resetInternal(normalizedKey);
  }

  private async resetInternal(normalizedKey: NormalizedRateLimitKey): Promise<void> {
    this.memoryBuckets.delete(normalizedKey);

    if (this.redisClient && this.isRedisConnected) {
      try {
        await this.redisClient.del(normalizedKey);
      } catch {
        // Best effort
      }
    }
  }

  async clearAll(): Promise<void> {
    this.memoryBuckets.clear();
    // Do not flush entire Redis in shared environment; only in test if client exists
    if (this.redisClient && this.isRedisConnected && process.env.NODE_ENV === 'test') {
      try {
        const keys = await this.redisClient.keys('fh:rl:*');
        if (keys.length > 0) {
          await this.redisClient.del(...keys);
        }
      } catch {
        // Best effort
      }
    }
  }

  private pruneExpiredBuckets(): void {
    const now = Date.now();
    for (const [key, bucket] of this.memoryBuckets.entries()) {
      if (now >= bucket.resetAt) {
        this.memoryBuckets.delete(key);
      }
    }
  }

  getActiveKeyCount(): number {
    return this.memoryBuckets.size;
  }

  // Testing hooks
  setMockRedisClient(client: Redis | null, isConnected = true): void {
    this.redisClient = client;
    this.isRedisConnected = isConnected;
  }

  isSharedActive(): boolean {
    return Boolean(this.redisClient && this.isRedisConnected);
  }
}
